import hashlib
import json
import stat
import subprocess

root = Path.cwd()
assert str(root) == "/Volumes/WD-Elements/a2a-t082-real-fixtures/fixture-04/state/review-copies/6c02cc18-b093-4fed-afc1-3d8881ff5d3b"
value = root / "src/value.txt"
details = root / "src/details.txt"
for path in (value, details):
    assert path.parent.resolve() == root / "src"
    assert not path.is_symlink()
original = {path: path.read_bytes() if path.exists() else None for path in (value, details)}

def snapshot():
    return {
        str(path.relative_to(root)): {
            "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            "mode": stat.S_IMODE(path.stat().st_mode),
        }
        for path in root.rglob("*") if path.is_file()
    }

before = snapshot()
argv = ["/usr/bin/python3", "-I", "-B", "acceptance/weak.py"]

def control_state():
    value.write_bytes(b"correct\\n")
    details.write_bytes(b"ready\\n")

def check(identifier, change):
    proc = subprocess.run(argv, cwd=root, capture_output=True, text=True)
    data = {str(path.relative_to(root)): repr(path.read_bytes()) if path.exists() else None for path in (value, details)}
    result = {
        "id": identifier,
        "change": change,
        "command": "/usr/bin/python3 -I -B acceptance/weak.py",
        "state": data,
        "result": {
            "exit_code": proc.returncode,
            "stdout": proc.stdout,
            "stderr": proc.stderr,
        },
    }
    print(json.dumps(result, ensure_ascii=False), flush=True)
    return proc.returncode

try:
    control_state()
    assert check("CONTROL", "临时完整对照：value=correct 加 LF，details=ready 加 LF") == 0
    mutations = [
        ("M1", "在完整对照上将 src/value.txt 改为 wrong 加 LF", value, b"wrong\\n"),
        ("M2", "在完整对照上将 src/value.txt 改为 correct，删除末尾 LF", value, b"correct"),
        ("M3", "在完整对照上删除 src/details.txt", details, None),
        ("M4", "在完整对照上将 src/details.txt 改为 pending 加 LF", details, b"pending\\n"),
        ("M5", "在完整对照上将 src/details.txt 改为 ready，删除末尾 LF", details, b"ready"),
    ]
    for identifier, change, path, content in mutations:
        control_state()
        if content is None:
            path.unlink()
        else:
            path.write_bytes(content)
        check(identifier, change)
finally:
    for path, content in original.items():
        if content is None:
            path.unlink(missing_ok=True)
        else:
            path.write_bytes(content)
    after = snapshot()
    assert before == after, "副本文件内容或模式未完全恢复"
    print(json.dumps({"restoration": "已恢复原始候选；文件集合、SHA-256 和模式全部一致", "snapshot": after}, ensure_ascii=False), flush=True)
`;
